// src/pages/notifications/NotificationPage.jsx
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useNotifications } from '../../hooks/UseNotifications';
import NotificationList from '../../components/notifications/NotificationList';

function NotificationPage() {
  const navigate = useNavigate();

  const {
    notifications,
    loading,
    error,
    limit,
    setLimit,
    page,
    setPage,
    filters,
    setFilters,
    refresh,
  } = useNotifications(50);

  const handleClickItem = (item) => {
    navigate(`/notifications/${item.id}`, { state: { notification: item } });
  };

  const handleSearch = () => {
    setPage(1);
    refresh();
  };

  return (
    <div className="page-container">
      <h1>알림 히스토리</h1>

      {/* 필터 바 (키워드/위험도/기간/개수) */}
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
        <input
          placeholder="키워드 검색"
          value={filters.keyword}
          onChange={(e) => setFilters((p) => ({ ...p, keyword: e.target.value }))}
        />

        <select
          value={filters.level}
          onChange={(e) => setFilters((p) => ({ ...p, level: e.target.value }))}
        >
          <option value="">전체</option>
          <option value="DANGER">DANGER</option>
          <option value="WARNING">WARNING</option>
          <option value="SAFE">SAFE</option>
        </select>

        <input
          type="date"
          value={filters.from}
          onChange={(e) => setFilters((p) => ({ ...p, from: e.target.value }))}
        />
        <input
          type="date"
          value={filters.to}
          onChange={(e) => setFilters((p) => ({ ...p, to: e.target.value }))}
        />

        <select value={limit} onChange={(e) => setLimit(Number(e.target.value) || 50)}>
          <option value={20}>20</option>
          <option value={50}>50</option>
          <option value={100}>100</option>
        </select>

        <button className="btn" onClick={handleSearch}>
          검색
        </button>
        <button className="btn" onClick={refresh}>
          새로고침
        </button>
      </div>

      {/* 페이지네이션(간단) */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 12 }}>
        <button className="btn" onClick={() => setPage((p) => Math.max(1, p - 1))}>
          이전
        </button>
        <span>page: {page}</span>
        <button className="btn" onClick={() => setPage((p) => p + 1)}>
          다음
        </button>
      </div>

      <NotificationList
        items={notifications}
        loading={loading}
        error={error}
        onItemClick={handleClickItem}
      />
    </div>
  );
}

export default NotificationPage;
